-- Native72472/player-cast spellclick summons a personal vehicle. Coordinate-only route import.
-- See pinned source and actor GUIDs in gilneas-bat-source.json; not a bulk historical import.
DROP TEMPORARY TABLE IF EXISTS `_1kycore_gilneas_bat_routes`;
CREATE TEMPORARY TABLE `_1kycore_gilneas_bat_routes` LIKE waypoint_data;
DROP TEMPORARY TABLE IF EXISTS `_1kycore_gilneas_bat_guard`;
CREATE TEMPORARY TABLE `_1kycore_gilneas_bat_guard` (ok INT NOT NULL);
LEFT JOIN `_1kycore_gilneas_bat_routes` s ON s.id=d.id AND s.point=d.point
WHERE d.id IN (3854001,3854003) AND (s.point IS NULL OR ABS(d.position_x-s.position_x)>0.01
OR ABS(d.position_y-s.position_y)>0.01 OR ABS(d.position_z-s.position_z)>0.01
OR d.orientation<>0 OR d.delay<>0 OR d.move_type<>1 OR d.action<>0 OR d.action_chance<>100 OR d.wpguid<>0) LIMIT 1;
LEFT JOIN waypoint_data d ON d.id=s.id AND d.point=s.point WHERE d.id IS NULL;
DROP TEMPORARY TABLE `_1kycore_gilneas_bat_guard`;
DROP TEMPORARY TABLE `_1kycore_gilneas_bat_routes`;
UPDATE creature_template SET npcflag=npcflag | 16777216 WHERE entry=38615 AND ScriptName='';
UPDATE npc_spellclick_spells SET cast_flags=1 WHERE npc_entry=38615 AND spell_id=72472 AND cast_flags=0;
UPDATE creature_template SET AIName='',ScriptName='npc_captured_riding_bat_38540'
WHERE entry=38540 AND ScriptName IN ('','npc_captured_riding_bat_38540');
SELECT 72472,'spell_gilneas_captured_bat_summon' WHERE NOT EXISTS
(SELECT 1 FROM spell_script_names WHERE spell_id=72472 AND ScriptName='spell_gilneas_captured_bat_summon');
